Implementa StandardSource agregando todos los checks. Calcular un 'quality summary' en metadata:

async evaluate(projectRoot: string): Promise<StandardSignal[]> {
  const results = await Promise.allSettled([
    checkTesting(projectRoot),
    checkLinting(projectRoot),
    checkTypeScript(projectRoot),
    checkDocumentation(projectRoot),
    checkPortability(projectRoot),
  ]);
  // flatten y filtrar errores
  return results
    .filter(r => r.status === 'fulfilled')
    .flatMap(r => (r as PromiseFulfilledResult<StandardSignal[]>).value);
}
